const fs = require(''fs'');
const before = JSON.parse(fs.readFileSync(''docs/performance-audits/cart.report.json'', ''utf8''));
const after = JSON.parse(fs.readFileSync(''docs/performance-audits/cart-after.report.json'', ''utf8''));

function compare(data, label) {
  const m = data.audits;
  const requests = m[''network-requests'']?.details?.items || [];

  return {
    label,
    score: (data.categories.performance.score * 100).toFixed(0),
    lcp: m[''largest-contentful-paint''].numericValue,
    tbt: m[''total-blocking-time''].numericValue,
    requests: requests.length,
    transfer: m[''total-byte-weight''].numericValue,
  };
}

const beforeMetrics = compare(before, ''BEFORE'');
const afterMetrics = compare(after, ''AFTER'');

console.log(''========== CART PAGE: BEFORE VS AFTER ==========\n'');
console.log(''Performance Score:'');
console.log(''  Before:'', beforeMetrics.score);
console.log(''  After: '', afterMetrics.score);
console.log(''  Change:'', (afterMetrics.score - beforeMetrics.score > 0 ? ''+'' : '''') + (afterMetrics.score - beforeMetrics.score));
console.log('''');
console.log(''LCP (Largest Contentful Paint):'');
console.log(''  Before:'', (beforeMetrics.lcp / 1000).toFixed(2) + ''s'');
console.log(''  After: '', (afterMetrics.lcp / 1000).toFixed(2) + ''s'');
console.log(''  Change:'', ((afterMetrics.lcp - beforeMetrics.lcp) / 1000).toFixed(2) + ''s'', ''('' + ((afterMetrics.lcp / beforeMetrics.lcp - 1) * 100).toFixed(1) + ''%)'');
console.log('''');
console.log(''TBT (Total Blocking Time):'');
console.log(''  Before:'', beforeMetrics.tbt.toFixed(0) + ''ms'');
console.log(''  After: '', afterMetrics.tbt.toFixed(0) + ''ms'');
console.log(''  Change:'', (afterMetrics.tbt - beforeMetrics.tbt).toFixed(0) + ''ms'', ''('' + ((afterMetrics.tbt / beforeMetrics.tbt - 1) * 100).toFixed(1) + ''%)'');
console.log('''');
console.log(''Network Requests:'');
console.log(''  Before:'', beforeMetrics.requests);
console.log(''  After: '', afterMetrics.requests);
console.log(''  Change:'', (afterMetrics.requests - beforeMetrics.requests));
console.log('''');
console.log(''Total Transfer Size:'');
console.log(''  Before:'', (beforeMetrics.transfer / 1024).toFixed(0) + '' KB'');
console.log(''  After: '', (afterMetrics.transfer / 1024).toFixed(0) + '' KB'');
console.log(''  Change:'', ((afterMetrics.transfer - beforeMetrics.transfer) / 1024).toFixed(0) + '' KB'', ''('' + ((afterMetrics.transfer / beforeMetrics.transfer - 1) * 100).toFixed(1) + ''%)'');
")

