const { PrismaClient } = require(''@prisma/client'');
const prisma = new PrismaClient();

prisma.vendor.findUnique({
  where: { slug: ''instapepz'' },
  select: { id: true, name: true, slug: true, allowedCategories: true }
}).then(vendor => {
  console.log(''✅ InstaPepz vendor permissions:'');
  console.log(JSON.stringify(vendor, null, 2));
  console.log(''\n📋 Summary:'');
  console.log(''  Vendor:'', vendor.name);
  console.log(''  Allowed Categories:'', vendor.allowedCategories.join('', ''));
  console.log(''  Can import peptides:'', vendor.allowedCategories.includes(''peptides'') ? ''✅ YES'' : ''❌ NO'');
  console.log(''  Can import amino-acids:'', vendor.allowedCategories.includes(''amino-acids'') ? ''✅ YES'' : ''❌ NO'');
  prisma.$disconnect();
}).catch(err => {
  console.error(''Error:'', err.message);
  prisma.$disconnect();
  process.exit(1);
});
